 v=json.loads((R/'validation-summary.json').read_text());sel=json.loads((R/'selection.json').read_text());audit=json.loads((R/'audit.json').read_text());diag=json.loads((R/'dev-diagnostics.json').read_text());counts=json.loads((R/'pre-training-counts.json').read_text())
 sec=sum(json.loads((R/f'{p}-summary.json').read_text())['wall_seconds'] for p in ('pilot','train','dev'));trainsec=sum(json.loads((R/f'learning-{a}-{s}.json').read_text())['wall_seconds'] for a in ('A','B') for s in SEEDS)
 lines=['# 両席抽出によるH方策蒸留：固定A/B対照','', '公開HとFrozen gen3を変更せず、元gen3からpolicy MLPだけを教師Hの着手分布へ蒸留した。実終局報酬による追加強化学習ではない。旧失敗/gateは163791fのまま保存。','',f'今回の事前gate: **{sel["gate"]}**。全3seed・epoch8固定、seed選別なし。固定3seedの推論であり、任意の更新seedへの一般化は未証明。確認試験はgate通過時のみ。','', '## 対照と経験量','', 'Aは実手番0のみ、Bは各段階で実手番0/1を32/32。共通256生成ゲーム/seedから各段階64適格ペアを採用し、各arm192ラベル/seed・8epoch・96Adam更新。両armの元ゲーム/段階ペアは同じ。前回の約364–369ラベル/seedとは総量が異なるため、旧失敗との直接的な因果差分にはしない。今回の主対照は同量のA/Bである。候補0/1・未完成教師・欠損片側はペアごと除外。','', '開発用は別96ゲーム/seedから各段階16ペアの両席、96ラベル/seed。1ゲーム複数局面は独立標本扱いしない。Bの半数はAに対して隣接する1ply後で、同段階でも局面内容の差は不可避。全seedで外生乱数列を共有するがモデルにより軌跡は異なる。A/Bラベルは半分重複。候補数・盤面内容・padding量は席に伴って変わり、同一FLOPsの比較ではない。lossは候補数ではなく局面単位平均を維持する。','', '教師は固定gen3/H幅4完成6ply。60秒は固定木完走の安全上限。全対象値を真のWDL/minimax値とは呼ばない。trunk/value/position/priorは凍結。元のAdam1e-4/CE+.05KL/batch16を保持。','', '## 新validation（勝1・引分0.5のpoint）','', '各行12新prefix×先後×3seed=72局。同一prefix内6局をまとめてbootstrap。B/publicとB/Aを事前の2主比較familyとしてBonferroni補正。A/public・単体は参考値。過去72局を合算しない。','', '|比較|point|通常95%CI|2比較補正CI|平均ゲーム得点差 (95%CI)|','|---|---:|---|---|---|']
 lines[lines.index('## 新validation（勝1・引分0.5のpoint）'):lines.index('## 新validation（勝1・引分0.5のpoint）')]=['## 実際の採用元ゲーム数','']+[f'- seed{s}: A/B共通のユニーク元ゲーム{c["unique_games"]["A"]}件（B={c["unique_games"]["B"]}）、段階別適格ペア '+str({k:v for k,v in c['train'].items() if k in ('12','20','28')}) for s,c in counts.items()]+['']
 def ci(x):return f'{x[0]*100:.2f}–{x[1]*100:.2f}%'
 for m,r in v.items():lines.append(f'|{m}|{r["point"]*100:.2f}%|{ci(r["point_ci95"])}|{ci(r["point_ci_bonferroni2"])}|{r["difference"]:+.3f} [{r["difference_ci95"][0]:+.3f},{r["difference_ci95"][1]:+.3f}]|')
